import{_ as p,a0 as d,w as o,s as h,ao as l,I as t,a1 as e,A as n,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 中查看已掛載的文件系統類型 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中查看已掛載的文件系統類型 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中查看已掛載的文件系統類型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中查看已掛載的文件系統類型 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180716 How To Find The Mounted Filesystem Type In Linux","title":"如何在 Linux 中查看已掛載的文件系統類型","tag":"201811","desc":""},"relativePath":"201811/20180716 How To Find The Mounted Filesystem Type In Linux.md","filePath":"[post].md"}'),c={name:"201811/20180716 How To Find The Mounted Filesystem Type In Linux.md"};function r(g,s,k,b,u,f){const i=d("Link");return o(),h("div",null,[s[16]||(s[16]=l(`<h1 id="如何在-linux-中查看已掛載的文件系統類型" tabindex="-1">如何在 Linux 中查看已掛載的文件系統類型 <a class="header-anchor" href="#如何在-linux-中查看已掛載的文件系統類型" aria-label="Permalink to “如何在 Linux 中查看已掛載的文件系統類型”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/07/filesystem-720x340.png" alt=""></p><p>如你所知，Linux 支持非常多的文件系統，例如 ext4、ext3、ext2、sysfs、securityfs、FAT16、FAT32、NTFS 等等，當前被使用最多的文件系統是 ext4。你曾經疑惑過你的 Linux 系統使用的是什麼類型的文件系統嗎？沒有疑惑過？不用擔心！我們將幫助你。本指南將解釋如何在類 Unix 的操作系統中查看已掛載的文件系統類型。</p><h3 id="在-linux-中查看已掛載的文件系統類型" tabindex="-1">在 Linux 中查看已掛載的文件系統類型 <a class="header-anchor" href="#在-linux-中查看已掛載的文件系統類型" aria-label="Permalink to “在 Linux 中查看已掛載的文件系統類型”">​</a></h3><p>有很多種方法可以在 Linux 中查看已掛載的文件系統類型，下面我將給出 8 種不同的方法。那現在就讓我們開始吧！</p><h4 id="方法-1-–-使用-findmnt-命令" tabindex="-1">方法 1 – 使用 findmnt 命令 <a class="header-anchor" href="#方法-1-–-使用-findmnt-命令" aria-label="Permalink to “方法 1 – 使用 findmnt 命令”">​</a></h4><p>這是查出文件系統類型最常使用的方法。<code>findmnt</code> 命令將列出所有已掛載的文件系統或者搜索出某個文件系統。<code>findmnt</code> 命令能夠在 <code>/etc/fstab</code>、<code>/etc/mtab</code> 或 <code>/proc/self/mountinfo</code> 這幾個文件中進行搜索。</p><p><code>findmnt</code> 預裝在大多數的 Linux 發行版中，因為它是 <code>util-linux</code> 包的一部分。如果 <code>findmnt</code> 命令不可用，你可以安裝這個軟件包。例如，你可以使用下面的命令在基於 Debian 的系統中安裝 <code>util-linux</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install util-linux</span></span></code></pre></div><p>下面讓我們繼續看看如何使用 <code>findmnt</code> 來找出已掛載的文件系統。</p><p>假如你只敲 <code>findmnt</code> 命令而不帶任何的參數或選項，它將像下面展示的那樣以樹狀圖形式列舉出所有已掛載的文件系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/findmnt-1.png" alt=""></p><p>正如你看到的那樣，<code>findmnt</code> 展示出了目標掛載點（<code>TARGET</code>）、源設備（<code>SOURCE</code>）、文件系統類型（<code>FSTYPE</code>）以及相關的掛載選項（<code>OPTIONS</code>），例如文件系統是否是可讀可寫或者只讀的。以我的系統為例，我的根（<code>/</code>）文件系統的類型是 EXT4 。</p><p>假如你不想以樹狀圖的形式來展示輸出，可以使用 <code>-l</code> 選項來以簡單平凡的形式來展示輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt -l</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/findmnt-2.png" alt=""></p><p>你還可以使用 <code>-t</code> 選項來列舉出特定類型的文件系統，例如下面展示的 <code>ext4</code> 文件系統類型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt -t ext4</span></span>
<span class="line"><span>TARGET  SOURCE    FSTYPE OPTIONS</span></span>
<span class="line"><span>/       /dev/sda2 ext4   rw,relatime,commit=360</span></span>
<span class="line"><span>└─/boot /dev/sda1 ext4   rw,relatime,commit=360,data=ordered</span></span></code></pre></div><p><code>findmnt</code> 還可以生成 <code>df</code> 類型的輸出，使用命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt --df</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt -D</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SOURCE     FSTYPE            SIZE    USED   AVAIL   USE% TARGET</span></span>
<span class="line"><span>dev        devtmpfs          3.9G       0    3.9G     0% /dev</span></span>
<span class="line"><span>run        tmpfs             3.9G    1.1M    3.9G     0% /run</span></span>
<span class="line"><span>/dev/sda2  ext4            456.3G  342.5G   90.6G    75% /</span></span>
<span class="line"><span>tmpfs      tmpfs             3.9G   32.2M    3.8G     1% /dev/shm</span></span>
<span class="line"><span>tmpfs      tmpfs             3.9G       0    3.9G     0% /sys/fs/cgroup</span></span>
<span class="line"><span>bpf        bpf                  0       0       0      - /sys/fs/bpf</span></span>
<span class="line"><span>tmpfs      tmpfs             3.9G    8.4M    3.9G     0% /tmp</span></span>
<span class="line"><span>/dev/loop0 squashfs         82.1M   82.1M       0   100% /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>/dev/sda1  ext4             92.8M   55.7M   30.1M    60% /boot</span></span>
<span class="line"><span>tmpfs      tmpfs           788.8M     32K  788.8M     0% /run/user/1000</span></span>
<span class="line"><span>gvfsd-fuse fuse.gvfsd-fuse      0       0       0      - /run/user/1000/gvfs</span></span></code></pre></div><p>你還可以展示某個特定設備或者掛載點的文件系統類型。</p><p>查看某個特定的設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt /dev/sda1</span></span>
<span class="line"><span>TARGET SOURCE    FSTYPE OPTIONS</span></span>
<span class="line"><span>/boot  /dev/sda1 ext4   rw,relatime,commit=360,data=ordered</span></span></code></pre></div><p>查看某個特定的掛載點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt /</span></span>
<span class="line"><span>TARGET SOURCE    FSTYPE OPTIONS</span></span>
<span class="line"><span>/      /dev/sda2 ext4   rw,relatime,commit=360</span></span></code></pre></div><p>你甚至還可以查看某個特定標籤的文件系統的類型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt LABEL=Storage</span></span></code></pre></div><p>更多詳情，請參考其 man 手冊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man findmnt</span></span></code></pre></div><p><code>findmnt</code> 命令已足夠完成在 Linux 中查看已掛載文件系統類型的任務，這個命令就是為了這個特定任務而生的。然而，還存在其他方法來查看文件系統的類型，假如你感興趣的話，請接着往下看。</p><h4 id="方法-2-–-使用-blkid-命令" tabindex="-1">方法 2 – 使用 blkid 命令 <a class="header-anchor" href="#方法-2-–-使用-blkid-命令" aria-label="Permalink to “方法 2 – 使用 blkid 命令”">​</a></h4><p><code>blkid</code> 命令被用來查找和打印塊設備的屬性。它也是 <code>util-linux</code> 包的一部分，所以你不必再安裝它。</p><p>為了使用 <code>blkid</code> 命令來查看某個文件系統的類型，可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ blkid /dev/sda1</span></span></code></pre></div><h4 id="方法-3-–-使用-df-命令" tabindex="-1">方法 3 – 使用 df 命令 <a class="header-anchor" href="#方法-3-–-使用-df-命令" aria-label="Permalink to “方法 3 – 使用 df 命令”">​</a></h4><p>在類 Unix 的操作系統中，<code>df</code> 命令被用來報告文件系統的磁盤空間使用情況。為了查看所有已掛載文件系統的類型，只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -T</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/df.png" alt=""></p><p>關於 <code>df</code> 命令的更多細節，可以參考下面的指南。</p>`,46)),t("ul",null,[t("li",null,[e(i,{href:"https://www.ostechnix.com/the-df-command-tutorial-with-examples-for-beginners/"},{default:n(()=>[...s[0]||(s[0]=[a("針對新手的 df 命令教程",-1)])]),_:1})])]),s[17]||(s[17]=l(`<p>同樣也可以參考其 man 手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man df</span></span></code></pre></div><h4 id="方法-4-–-使用-file-命令" tabindex="-1">方法 4 – 使用 file 命令 <a class="header-anchor" href="#方法-4-–-使用-file-命令" aria-label="Permalink to “方法 4 – 使用 file 命令”">​</a></h4><p><code>file</code> 命令可以判讀出某個特定文件的類型，即便該文件沒有文件後綴名也同樣適用。</p><p>運行下面的命令來找出某個特定分區的文件系統類型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo file -sL /dev/sda1</span></span>
<span class="line"><span>[sudo] password for sk:</span></span>
<span class="line"><span>/dev/sda1: Linux rev 1.0 ext4 filesystem data, UUID=83a1dbbf-1e15-4b45-94fe-134d3872af96 (needs journal recovery) (extents) (large files) (huge files)</span></span></code></pre></div><p>查看其 man 手冊可以知曉更多細節：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man file</span></span></code></pre></div><h4 id="方法-5-–-使用-fsck-命令" tabindex="-1">方法 5 – 使用 fsck 命令 <a class="header-anchor" href="#方法-5-–-使用-fsck-命令" aria-label="Permalink to “方法 5 – 使用 fsck 命令”">​</a></h4><p><code>fsck</code> 命令被用來檢查某個文件系統是否健全或者修復它。你可以像下面那樣通過將分區名字作為 <code>fsck</code> 的參數來查看該分區的文件系統類型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fsck -N /dev/sda1</span></span>
<span class="line"><span>fsck from util-linux 2.32</span></span>
<span class="line"><span>[/usr/bin/fsck.ext4 (1) -- /boot] fsck.ext4 /dev/sda1</span></span></code></pre></div><p>如果想知道更多的內容，請查看其 man 手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man fsck</span></span></code></pre></div><h4 id="方法-6-–-使用-fstab-命令" tabindex="-1">方法 6 – 使用 fstab 命令 <a class="header-anchor" href="#方法-6-–-使用-fstab-命令" aria-label="Permalink to “方法 6 – 使用 fstab 命令”">​</a></h4><p><code>fstab</code> 是一個包含文件系統靜態信息的文件。這個文件通常包含了掛載點、文件系統類型和掛載選項等信息。</p><p>要查看某個文件系統的類型，只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/fstab</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/fstab.png" alt=""></p><p>更多詳情，請查看其 man 手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man fstab</span></span></code></pre></div><h4 id="方法-7-–-使用-lsblk-命令" tabindex="-1">方法 7 – 使用 lsblk 命令 <a class="header-anchor" href="#方法-7-–-使用-lsblk-命令" aria-label="Permalink to “方法 7 – 使用 lsblk 命令”">​</a></h4><p><code>lsblk</code> 命令可以展示設備的信息。</p><p>要展示已掛載文件系統的信息，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsblk -f</span></span>
<span class="line"><span>NAME   FSTYPE   LABEL  UUID                                 MOUNTPOINT</span></span>
<span class="line"><span>loop0  squashfs                                             /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>sda</span></span>
<span class="line"><span>├─sda1 ext4            83a1dbbf-1e15-4b45-94fe-134d3872af96 /boot</span></span>
<span class="line"><span>├─sda2 ext4            4d25ddb0-5b20-40b4-ae35-ef96376d6594 /</span></span>
<span class="line"><span>└─sda3 swap            1f8f5e2e-7c17-4f35-97e6-8bce7a4849cb [SWAP]</span></span>
<span class="line"><span>sr0</span></span></code></pre></div><p>更多細節，可以參考它的 man 手冊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man lsblk</span></span></code></pre></div><h4 id="方法-8-–-使用-mount-命令" tabindex="-1">方法 8 – 使用 mount 命令 <a class="header-anchor" href="#方法-8-–-使用-mount-命令" aria-label="Permalink to “方法 8 – 使用 mount 命令”">​</a></h4><p><code>mount</code> 被用來在類 Unix 系統中掛載本地或遠程的文件系統。</p><p>要使用 <code>mount</code> 命令查看文件系統的類型，可以像下面這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mount | grep &quot;^/dev&quot;</span></span>
<span class="line"><span>/dev/sda2 on / type ext4 (rw,relatime,commit=360)</span></span>
<span class="line"><span>/dev/sda1 on /boot type ext4 (rw,relatime,commit=360,data=ordered)</span></span></code></pre></div><p>更多詳情，請參考其 man 手冊的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man mount</span></span></code></pre></div><p>好了，上面便是今天的全部內容了。現在你知道了 8 種不同的 Linux 命令來查看已掛載的 Linux 文件系統的類型。假如你知道其他的命令來完成同樣的任務，請在下面的評論部分讓我們知曉，我將確認並相應地升級本教程。</p><p>更過精彩內容即將呈現，請保持關注！</p><hr>`,35)),t("p",null,[s[2]||(s[2]=a("via: ",-1)),e(i,{href:"https://www.ostechnix.com/how-to-find-the-mounted-filesystem-type-in-linux/"},{default:n(()=>[...s[1]||(s[1]=[a("https://www.ostechnix.com/how-to-find-the-mounted-filesystem-type-in-linux/",-1)])]),_:1})]),t("p",null,[s[7]||(s[7]=a("作者：",-1)),e(i,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...s[3]||(s[3]=[a("SK",-1)])]),_:1}),s[8]||(s[8]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[4]||(s[4]=[a("lujun9972",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),e(i,{href:"https://github.com/FSSlc"},{default:n(()=>[...s[5]||(s[5]=[a("FSSlc",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[6]||(s[6]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const v=p(c,[["render",r]]);export{y as __pageData,v as default};
